import{_ as t,c as h,o as i,a2 as g}from"./chunks/framework.B7el9cAC.js";const e=JSON.parse('{"title":"Mục 6.8 – Tác Động Của CNTT Đến Xã Hội","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-6/6.8-tac-dong-cntt.md","filePath":"chuong-6/6.8-tac-dong-cntt.md","lastUpdated":1775365196000}'),c={name:"chuong-6/6.8-tac-dong-cntt.md"};function o(a,n,u,r,l,d){return i(),h("div",null,[...n[0]||(n[0]=[g(`<h1 id="muc-6-8-–-tac-đong-cua-cntt-đen-xa-hoi" tabindex="-1">Mục 6.8 – Tác Động Của CNTT Đến Xã Hội <a class="header-anchor" href="#muc-6-8-–-tac-đong-cua-cntt-đen-xa-hoi" aria-label="Permalink to &quot;Mục 6.8 – Tác Động Của CNTT Đến Xã Hội&quot;">​</a></h1><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><p><strong>Công nghệ thông tin đã thay đổi thế giới như thế nào?</strong></p><p>Năm 2000, để mua một đôi giày:</p><ul><li>Bạn phải đến cửa hàng</li><li>Trả tiền mặt</li><li>Hỏi nhân viên để tìm sản phẩm</li></ul><p>Năm 2024, để mua một đôi giày:</p><ul><li>Mở điện thoại, tìm kiếm &quot;giày thể thao&quot;</li><li>Shopee gợi ý đúng loại bạn thích (dựa trên dữ liệu)</li><li>Đặt hàng → 2 ngày giao tận nhà</li><li>Thanh toán không cần tiền mặt</li></ul><p><strong>Trong chưa đầy 25 năm</strong>, CNTT đã thay đổi hoàn toàn cách chúng ta mua sắm, học tập, làm việc, giao tiếp, và giải trí. Và sự thay đổi này <strong>chưa dừng lại</strong>.</p><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="tac-đong-tich-cuc-cua-cntt-đen-xa-hoi" tabindex="-1">Tác động tích cực của CNTT đến xã hội <a class="header-anchor" href="#tac-đong-tich-cuc-cua-cntt-đen-xa-hoi" aria-label="Permalink to &quot;Tác động tích cực của CNTT đến xã hội&quot;">​</a></h3><p><strong>1. Giáo dục (Education):</strong></p><ul><li><strong>Democratization of Education (Dân chủ hóa giáo dục):</strong> Học sinh ở vùng sâu vùng xa có thể học từ giáo viên giỏi nhất qua internet</li><li><strong>Học liệu phong phú:</strong> Video, bài giảng tương tác, sách điện tử, MOOCs (Khóa học trực tuyến)</li><li><strong>Cá nhân hóa học tập:</strong> AI điều chỉnh nội dung theo tốc độ và phong cách học của từng người</li><li>Ví dụ: Khan Academy, Coursera, YouTube Education</li></ul><p><strong>2. Y tế (Healthcare):</strong></p><ul><li><strong>Telemedicine (Khám bệnh từ xa):</strong> Bác sĩ tư vấn qua video call, xem kết quả xét nghiệm online</li><li><strong>Chẩn đoán AI:</strong> AI phát hiện ung thư từ ảnh X-quang chính xác hơn bác sĩ trong một số trường hợp</li><li><strong>Hồ sơ bệnh án điện tử:</strong> Bác sĩ khắp nơi có thể xem lịch sử bệnh của bệnh nhân</li><li><strong>Thiết bị đeo thông minh:</strong> Smartwatch theo dõi nhịp tim, phát hiện bất thường</li></ul><p><strong>3. Kinh tế (Economy):</strong></p><ul><li><strong>E-commerce:</strong> Mua bán không giới hạn không gian, thời gian</li><li><strong>Fintech:</strong> Thanh toán số, vay tiền online, đầu tư điện tử</li><li><strong>Startup ecosystem:</strong> Chi phí khởi nghiệp giảm mạnh nhờ cloud computing</li><li><strong>Gig economy:</strong> Freelance, remote work, công việc linh hoạt</li></ul><p><strong>4. Giao tiếp và xã hội:</strong></p><ul><li>Kết nối người thân ở xa không tốn kém</li><li>Cộng đồng toàn cầu cho mọi sở thích</li><li>Tiếng nói của công dân được khuếch đại</li></ul><p><strong>5. Hành chính công:</strong></p><ul><li>Dịch vụ công trực tuyến: đăng ký khai sinh, nộp thuế, đổi bằng lái xe online</li><li>Giảm tham nhũng qua minh bạch hóa quy trình</li><li>Chính phủ điện tử (e-Government)</li></ul><h3 id="tac-đong-tieu-cuc-cua-cntt-đen-xa-hoi" tabindex="-1">Tác động tiêu cực của CNTT đến xã hội <a class="header-anchor" href="#tac-đong-tieu-cuc-cua-cntt-đen-xa-hoi" aria-label="Permalink to &quot;Tác động tiêu cực của CNTT đến xã hội&quot;">​</a></h3><p><strong>1. Mất việc làm do tự động hóa (Automation):</strong></p><ul><li>Robot và AI thay thế công nhân trong nhà máy, lái xe tải, kế toán, dịch thuật...</li><li><strong>Ước tính:</strong> 47% công việc hiện tại có nguy cơ bị tự động hóa trong 20 năm tới (McKinsey)</li><li>Yêu cầu tái đào tạo lực lượng lao động quy mô lớn</li></ul><p><strong>2. Khoảng cách số (Digital Divide):</strong></p><ul><li>Người có internet, thiết bị, kỹ năng số → có nhiều cơ hội hơn</li><li>Người thiếu các yếu tố này → bị bỏ lại phía sau</li><li>Khoảng cách giữa thành thị-nông thôn, giàu-nghèo, già-trẻ</li></ul><p><strong>3. Tin giả (Misinformation &amp; Disinformation):</strong></p><ul><li>Tin sai lan truyền nhanh hơn tin thật trên mạng xã hội</li><li><strong>Deepfake:</strong> Video/audio giả mạo người thật bằng AI</li><li>Ảnh hưởng đến bầu cử, sức khỏe cộng đồng (chống vaccine sai lệch), xã hội</li></ul><p><strong>4. Vấn đề riêng tư và giám sát:</strong></p><ul><li>Dữ liệu cá nhân bị thu thập, bán cho bên thứ ba</li><li>Giám sát qua camera AI, nhận dạng khuôn mặt</li><li>&quot;Big Tech&quot; nắm giữ quyền lực dữ liệu khổng lồ</li></ul><p><strong>5. Phụ thuộc và nghiện công nghệ:</strong></p><ul><li>Xã hội quá phụ thuộc vào các hệ thống số → dễ bị tê liệt khi xảy ra sự cố</li><li>Nghiện điện thoại, mạng xã hội ảnh hưởng sức khỏe tâm thần</li><li>Mất kỹ năng xã hội trực tiếp, cô đơn mặc dù &quot;kết nối&quot; ảo</li></ul><h3 id="chuyen-đoi-so-digital-transformation" tabindex="-1">Chuyển đổi số (Digital Transformation) <a class="header-anchor" href="#chuyen-đoi-so-digital-transformation" aria-label="Permalink to &quot;Chuyển đổi số (Digital Transformation)&quot;">​</a></h3><p><strong>Chuyển đổi số</strong> là quá trình tích hợp công nghệ số vào tất cả các lĩnh vực hoạt động, thay đổi cơ bản cách tổ chức/doanh nghiệp/xã hội hoạt động.</p><p><strong>Cách mạng công nghiệp 4.0 (Industry 4.0):</strong></p><ul><li><strong>IoT (Internet of Things):</strong> Thiết bị kết nối internet – tủ lạnh thông minh, nhà thông minh</li><li><strong>AI/Machine Learning:</strong> Tự động hóa thông minh</li><li><strong>Big Data:</strong> Phân tích dữ liệu khổng lồ</li><li><strong>Cloud Computing:</strong> Lưu trữ và xử lý đám mây</li><li><strong>Blockchain:</strong> Dữ liệu phi tập trung, minh bạch</li></ul><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><p><strong>Công nghệ là &quot;trung tính&quot; – con người quyết định tác động</strong></p><p>CNTT giống như con dao:</p><ul><li><strong>Dùng để nấu ăn</strong> → tốt, có ích</li><li><strong>Dùng để làm hại người</strong> → xấu, nguy hiểm</li><li><strong>Trẻ em dùng không cẩn thận</strong> → nguy hiểm ngay cả khi không có ý xấu</li></ul><p>Tương tự:</p><ul><li><strong>Mạng xã hội:</strong> Kết nối bạn bè hay lan truyền thù ghét?</li><li><strong>AI:</strong> Chẩn đoán ung thư hay tạo deepfake lừa đảo?</li><li><strong>Blockchain:</strong> Giao dịch minh bạch hay rửa tiền?</li></ul><p><strong>Câu trả lời không nằm ở công nghệ – mà ở cách xã hội, pháp luật, và đạo đức hướng dẫn việc sử dụng nó.</strong></p><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="qua-trinh-cong-nghe-moi-tac-đong-đen-xa-hoi" tabindex="-1">Quá trình công nghệ mới tác động đến xã hội: <a class="header-anchor" href="#qua-trinh-cong-nghe-moi-tac-đong-đen-xa-hoi" aria-label="Permalink to &quot;Quá trình công nghệ mới tác động đến xã hội:&quot;">​</a></h3><ol><li><strong>Phát minh công nghệ</strong> → Công nghệ mới xuất hiện (ví dụ: mạng xã hội, AI, smartphone)</li><li><strong>Áp dụng đại trà</strong> → Công nghệ được đông đảo người dùng sử dụng</li><li><strong>Tác động tích cực xuất hiện</strong> → Lợi ích rõ ràng (kết nối, tiện lợi, năng suất)</li><li><strong>Tác động tiêu cực xuất hiện</strong> → Vấn đề nảy sinh (nghiện, tin giả, mất việc)</li><li><strong>Xã hội phản ứng</strong> → Dư luận, nghiên cứu, báo chí đặt câu hỏi</li><li><strong>Pháp luật điều chỉnh</strong> → Chính phủ ban hành luật, quy định</li><li><strong>Công nghệ/xã hội thích nghi</strong> → Tìm điểm cân bằng mới</li></ol><h3 id="vi-du-mang-xa-hoi-va-xa-hoi-vn" tabindex="-1">Ví dụ: Mạng xã hội và xã hội VN: <a class="header-anchor" href="#vi-du-mang-xa-hoi-va-xa-hoi-vn" aria-label="Permalink to &quot;Ví dụ: Mạng xã hội và xã hội VN:&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2009: Facebook vào VN → Kết nối bạn bè, chia sẻ thông tin</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>2015: Bùng nổ tin giả, lừa đảo online → Dư luận lo ngại</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>2018: Luật An ninh mạng được thông qua</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>2019-nay: Xử lý vi phạm, nền tảng phải tuân thủ yêu cầu gỡ nội dung</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>Hiện tại: Vẫn đang tìm điểm cân bằng giữa tự do ngôn luận và an toàn</span></span></code></pre></div><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-co-ban-cntt-thay-đoi-nganh-giao-duc" tabindex="-1">Ví dụ 1 – Cơ bản: CNTT thay đổi ngành giáo dục <a class="header-anchor" href="#vi-du-1-–-co-ban-cntt-thay-đoi-nganh-giao-duc" aria-label="Permalink to &quot;Ví dụ 1 – Cơ bản: CNTT thay đổi ngành giáo dục&quot;">​</a></h3><p><strong>Trước CNTT (trước 2000):</strong></p><ul><li>Học sinh chỉ học từ giáo viên trong lớp</li><li>Tài liệu giới hạn trong sách giáo khoa và thư viện</li><li>Học sinh vùng nông thôn bất lợi hơn thành phố</li></ul><p><strong>Sau CNTT (2024):</strong></p><ul><li>Học sinh có thể học từ giáo viên giỏi nhất thế giới qua YouTube, Coursera</li><li>Tài liệu vô hạn, cập nhật liên tục</li><li>Học sinh ở Điện Biên có thể học cùng tài liệu với học sinh TP.HCM</li><li>AI tutor hỗ trợ 24/7</li></ul><p><strong>Tác động tiêu cực song song:</strong></p><ul><li>Học sinh tập trung kém hơn (điện thoại trong lớp)</li><li>Gian lận trong thi cử dễ dàng hơn</li><li>Thầy cô phải cạnh tranh với YouTube về sự hấp dẫn</li></ul><hr><h3 id="vi-du-2-–-thuc-te-tu-đong-hoa-va-thi-truong-lao-đong-vn" tabindex="-1">Ví dụ 2 – Thực tế: Tự động hóa và thị trường lao động VN <a class="header-anchor" href="#vi-du-2-–-thuc-te-tu-đong-hoa-va-thi-truong-lao-đong-vn" aria-label="Permalink to &quot;Ví dụ 2 – Thực tế: Tự động hóa và thị trường lao động VN&quot;">​</a></h3><p><strong>Các nghề đang bị ảnh hưởng ở VN:</strong></p><ul><li><strong>Công nhân may:</strong> Robot may công nghiệp thay thế một phần; VN đang có lợi thế nhân công rẻ nhưng sẽ giảm dần</li><li><strong>Kế toán, nhân viên ngân hàng:</strong> Phần mềm kế toán tự động, chatbot xử lý giao dịch</li><li><strong>Nhân viên bán lẻ:</strong> Tự checkout (thanh toán tự động), mua sắm online</li><li><strong>Lái xe:</strong> Xe tự lái đang phát triển (chưa phổ biến tại VN nhưng xu hướng tất yếu)</li></ul><p><strong>Nghề mới xuất hiện nhờ CNTT:</strong></p><ul><li>Lập trình viên, kỹ sư AI</li><li>Content creator, KOL, YouTuber</li><li>Quản lý logistics thương mại điện tử</li><li>Chuyên gia an ninh mạng</li><li>UX/UI Designer</li></ul><hr><h3 id="vi-du-3-–-nang-cao-deepfake-va-thach-thuc-cho-xa-hoi" tabindex="-1">Ví dụ 3 – Nâng cao: Deepfake và thách thức cho xã hội <a class="header-anchor" href="#vi-du-3-–-nang-cao-deepfake-va-thach-thuc-cho-xa-hoi" aria-label="Permalink to &quot;Ví dụ 3 – Nâng cao: Deepfake và thách thức cho xã hội&quot;">​</a></h3><p><strong>Deepfake là gì?</strong> Deepfake là video/audio/ảnh được tạo ra bằng AI để giả mạo một người thật – đặt lời nói/hành động vào miệng người đó mà họ không hề làm.</p><p><strong>Ứng dụng tốt:</strong></p><ul><li>Phục dựng khuôn mặt diễn viên đã mất trong phim</li><li>Dịch thuật video tự động khớp miệng</li><li>Giáo dục: mô phỏng nhân vật lịch sử</li></ul><p><strong>Ứng dụng xấu:</strong></p><ul><li>Fake porn (video giả mạo không đồng ý)</li><li>Tin giả: Tạo video giả lãnh đạo tuyên bố điều chưa từng nói</li><li>Lừa đảo: Giả giọng CEO gọi điện yêu cầu chuyển tiền</li></ul><p><strong>Thách thức pháp lý:</strong> Luật chưa đủ nhanh để theo kịp công nghệ. VN chưa có quy định cụ thể về deepfake.</p><p><strong>Cách nhận biết Deepfake:</strong></p><ul><li>Mắt không nháy đúng nhịp, chuyển động không tự nhiên</li><li>Ánh sáng/bóng đổ không khớp khuôn mặt</li><li>Viền khuôn mặt mờ hoặc nhòe khi chuyển động</li><li>Kiểm tra nguồn gốc video</li></ul><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="so-sanh-tac-đong-tich-cuc-va-tieu-cuc-cua-cntt" tabindex="-1">So sánh tác động tích cực và tiêu cực của CNTT <a class="header-anchor" href="#so-sanh-tac-đong-tich-cuc-va-tieu-cuc-cua-cntt" aria-label="Permalink to &quot;So sánh tác động tích cực và tiêu cực của CNTT&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Lĩnh vực</th><th>Tác động tích cực</th><th>Tác động tiêu cực</th></tr></thead><tbody><tr><td>Giáo dục</td><td>Học liệu phong phú, tiếp cận bình đẳng</td><td>Phân tâm, gian lận</td></tr><tr><td>Y tế</td><td>Khám từ xa, AI chẩn đoán</td><td>Lo ngại riêng tư y tế</td></tr><tr><td>Kinh tế</td><td>E-commerce, startup dễ hơn</td><td>Tự động hóa thay thế lao động</td></tr><tr><td>Xã hội</td><td>Kết nối không giới hạn</td><td>Cô đơn ảo, nghiện mạng xã hội</td></tr><tr><td>Thông tin</td><td>Tiếp cận tức thì</td><td>Tin giả, deepfake lan tràn</td></tr><tr><td>Hành chính</td><td>Dịch vụ công online</td><td>Nguy cơ bảo mật dữ liệu công dân</td></tr></tbody></table><h3 id="so-sanh-cuoc-song-truoc-va-sau-cntt-pho-bien" tabindex="-1">So sánh cuộc sống trước và sau CNTT phổ biến <a class="header-anchor" href="#so-sanh-cuoc-song-truoc-va-sau-cntt-pho-bien" aria-label="Permalink to &quot;So sánh cuộc sống trước và sau CNTT phổ biến&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hoạt động</th><th>Trước CNTT</th><th>Sau CNTT</th></tr></thead><tbody><tr><td>Mua sắm</td><td>Đến cửa hàng</td><td>Shopee, Lazada</td></tr><tr><td>Gửi thư</td><td>Bưu điện, 5-7 ngày</td><td>Email, 0 giây</td></tr><tr><td>Tìm đường</td><td>Bản đồ giấy, hỏi thăm</td><td>Google Maps</td></tr><tr><td>Học tập</td><td>Chỉ trong trường</td><td>Bất cứ đâu, bất cứ lúc nào</td></tr><tr><td>Ngân hàng</td><td>Đến chi nhánh</td><td>App banking</td></tr><tr><td>Xem phim</td><td>Rạp chiếu bóng</td><td>Netflix, YouTube</td></tr><tr><td>Tìm việc</td><td>Báo giấy, qua quen biết</td><td>LinkedIn, TopCV</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>✅ CNTT có <strong>cả tác động tích cực và tiêu cực</strong> với xã hội</li><li>✅ <strong>Tích cực:</strong> Giáo dục bình đẳng, y tế tiên tiến, kinh tế phát triển, kết nối toàn cầu</li><li>✅ <strong>Tiêu cực:</strong> Mất việc do tự động hóa, khoảng cách số, tin giả, vấn đề riêng tư</li><li>✅ <strong>Digital Divide (Khoảng cách số)</strong> = bất bình đẳng giữa người có/không có công nghệ</li><li>✅ <strong>Deepfake</strong> = video/âm thanh giả mạo người thật bằng AI</li><li>✅ <strong>Cách mạng 4.0</strong> = IoT + AI + Big Data + Cloud + Blockchain</li><li>✅ <strong>Chuyển đổi số</strong> = tích hợp công nghệ số vào mọi lĩnh vực hoạt động</li><li>✅ Công nghệ <strong>trung tính</strong> – con người và xã hội quyết định tác động tốt hay xấu</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><h3 id="cau-1-de-khoang-cach-so-digital-divide-la-gi" tabindex="-1">Câu 1 (Dễ): &quot;Khoảng cách số (Digital Divide)&quot; là gì? <a class="header-anchor" href="#cau-1-de-khoang-cach-so-digital-divide-la-gi" aria-label="Permalink to &quot;Câu 1 (Dễ): &quot;Khoảng cách số (Digital Divide)&quot; là gì?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Khoảng cách số là sự bất bình đẳng giữa những người có khả năng tiếp cận và sử dụng công nghệ thông tin (internet, thiết bị, kỹ năng số) và những người không có khả năng này. Điều này tạo ra bất bình đẳng về cơ hội giáo dục, việc làm, và tham gia kinh tế-xã hội.</p></blockquote><hr><h3 id="cau-2-de-cntt-co-tac-đong-gi-tich-cuc-đen-linh-vuc-y-te" tabindex="-1">Câu 2 (Dễ): CNTT có tác động gì tích cực đến lĩnh vực y tế? <a class="header-anchor" href="#cau-2-de-cntt-co-tac-đong-gi-tich-cuc-đen-linh-vuc-y-te" aria-label="Permalink to &quot;Câu 2 (Dễ): CNTT có tác động gì tích cực đến lĩnh vực y tế?&quot;">​</a></h3><p><strong>A.</strong> Làm cho bác sĩ không còn cần thiết<br><strong>B.</strong> Chỉ giúp bệnh nhân đặt lịch hẹn online<br><strong>C.</strong> Telemedicine, AI chẩn đoán, hồ sơ bệnh án điện tử, thiết bị theo dõi sức khỏe<br><strong>D.</strong> Giảm chi phí bệnh viện xuống bằng 0</p><blockquote><p><strong>Đáp án: C</strong> – CNTT tác động đến y tế qua nhiều chiều: telemedicine (khám từ xa), AI hỗ trợ chẩn đoán, hồ sơ bệnh án điện tử chia sẻ được, và thiết bị đeo theo dõi sức khỏe liên tục.</p></blockquote><hr><h3 id="cau-3-trung-binh-tai-sao-tu-đong-hoa-co-the-gay-ra-van-đe-xa-hoi-nghiem-trong" tabindex="-1">Câu 3 (Trung bình): Tại sao tự động hóa có thể gây ra vấn đề xã hội nghiêm trọng? <a class="header-anchor" href="#cau-3-trung-binh-tai-sao-tu-đong-hoa-co-the-gay-ra-van-đe-xa-hoi-nghiem-trong" aria-label="Permalink to &quot;Câu 3 (Trung bình): Tại sao tự động hóa có thể gây ra vấn đề xã hội nghiêm trọng?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Tự động hóa thay thế lao động con người bằng robot và AI có thể gây ra: (1) <strong>Mất việc làm hàng loạt</strong> ở các ngành sản xuất, dịch vụ lặp đi lặp lại; (2) <strong>Bất bình đẳng thu nhập</strong> tăng – người sở hữu công nghệ giàu hơn, lao động phổ thông khó kiếm việc; (3) <strong>Áp lực tái đào tạo</strong> khổng lồ cho lực lượng lao động; (4) <strong>Bất ổn xã hội</strong> nếu không có chính sách hỗ trợ kịp thời. Tuy nhiên, tự động hóa cũng tạo ra nghề mới – vấn đề là tốc độ mất việc nhanh hơn tốc độ tạo việc mới trong ngắn hạn.</p></blockquote><hr><h3 id="cau-4-trung-binh-deepfake-la-gi-va-tai-sao-no-nguy-hiem" tabindex="-1">Câu 4 (Trung bình): Deepfake là gì và tại sao nó nguy hiểm? <a class="header-anchor" href="#cau-4-trung-binh-deepfake-la-gi-va-tai-sao-no-nguy-hiem" aria-label="Permalink to &quot;Câu 4 (Trung bình): Deepfake là gì và tại sao nó nguy hiểm?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Deepfake là nội dung (video, âm thanh, ảnh) được tạo ra hoặc chỉnh sửa bằng AI để giả mạo một người thật – tạo ra cảnh người đó nói hoặc làm điều họ không hề làm.</p><p>Nguy hiểm vì: (1) Tạo tin giả có độ tin cậy cao (video trông như thật); (2) Xâm phạm danh dự, nhân phẩm nạn nhân; (3) Dùng để lừa đảo tài chính (giả giọng CEO gọi điện); (4) Can thiệp vào bầu cử, chính trị; (5) Pháp luật chưa đủ để xử lý hiệu quả.</p></blockquote><hr><h3 id="cau-5-van-dung-hay-phan-tich-tac-đong-tich-cuc-va-tieu-cuc-cua-mang-xa-hoi-đoi-voi-hoc-sinh-thpt-đe-xuat-cach-su-dung-mang-xa-hoi-co-ich" tabindex="-1">Câu 5 (Vận dụng): Hãy phân tích tác động tích cực VÀ tiêu cực của mạng xã hội đối với học sinh THPT. Đề xuất cách sử dụng mạng xã hội có ích. <a class="header-anchor" href="#cau-5-van-dung-hay-phan-tich-tac-đong-tich-cuc-va-tieu-cuc-cua-mang-xa-hoi-đoi-voi-hoc-sinh-thpt-đe-xuat-cach-su-dung-mang-xa-hoi-co-ich" aria-label="Permalink to &quot;Câu 5 (Vận dụng): Hãy phân tích tác động tích cực VÀ tiêu cực của mạng xã hội đối với học sinh THPT. Đề xuất cách sử dụng mạng xã hội có ích.&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong></p><p><strong>Tác động tích cực:</strong></p><ul><li>Kết nối với bạn bè, thầy cô, gia đình</li><li>Học hỏi qua nội dung giáo dục (YouTube, Facebook groups)</li><li>Tìm kiếm thông tin tuyển sinh, học bổng</li><li>Thể hiện tài năng, phát triển kỹ năng sáng tạo nội dung</li></ul><p><strong>Tác động tiêu cực:</strong></p><ul><li>Mất tập trung trong học tập</li><li>So sánh bản thân → tự ti, lo âu</li><li>Ngủ muộn vì lướt mạng</li><li>Tiếp xúc với thông tin sai lệch</li><li>Nguy cơ bị bắt nạt trực tuyến</li></ul><p><strong>Đề xuất sử dụng có ích:</strong></p><ol><li>Đặt giờ sử dụng cố định (ví dụ: chỉ sau 5h chiều)</li><li>Follow các tài khoản giáo dục thay vì giải trí thuần túy</li><li>Tham gia nhóm học tập, trao đổi bài</li><li>Tắt thông báo khi học</li><li>Không sử dụng 1 giờ trước ngủ</li></ol></blockquote><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Quan niệm sai</th><th>Thực tế đúng</th></tr></thead><tbody><tr><td>&quot;CNTT chỉ có lợi, không có hại&quot;</td><td>Mọi công nghệ đều có tác động hai chiều</td></tr><tr><td>&quot;Công nghệ tự nhiên là tốt, hại do con người&quot;</td><td>Cả thiết kế công nghệ (ví dụ: thuật toán gây nghiện) cũng góp phần</td></tr><tr><td>&quot;Chỉ người già mới bị khoảng cách số&quot;</td><td>Thanh thiếu niên ở vùng thiếu điện, internet cũng bị khoảng cách số</td></tr><tr><td>&quot;AI sẽ tạo ra nhiều việc hơn là mất việc&quot;</td><td>Có thể đúng về dài hạn nhưng quá trình chuyển đổi gây đau đớn ngắn hạn</td></tr><tr><td>&quot;Deepfake dễ phân biệt&quot;</td><td>Deepfake ngày càng khó phân biệt với video thật</td></tr><tr><td>&quot;Chuyển đổi số chỉ là của doanh nghiệp&quot;</td><td>Học sinh, gia đình, cơ quan nhà nước đều đang chuyển đổi số</td></tr><tr><td>&quot;Internet xóa bỏ mọi rào cản về thông tin&quot;</td><td>Bong bóng lọc (filter bubble) và thuật toán đề xuất tạo ra các buồng vang (echo chamber)</td></tr><tr><td>&quot;Mạng xã hội kết nối mọi người với nhau tốt hơn thực tế&quot;</td><td>Mạng xã hội có thể tăng kết nối bề mặt nhưng giảm chất lượng các mối quan hệ sâu sắc</td></tr><tr><td>&quot;Automation chỉ thay thế lao động phổ thông, không ảnh hưởng lao động tri thức&quot;</td><td>Automation ngày càng thay thế cả công việc tri thức như phân tích, viết lách cơ bản</td></tr><tr><td>&quot;Thương mại điện tử chỉ có lợi cho người tiêu dùng&quot;</td><td>TMĐT gây tác động tiêu cực đến cửa hàng nhỏ và thay đổi cơ cấu việc làm bán lẻ</td></tr><tr><td>&quot;AI không có thiên kiến (bias) vì máy tính khách quan&quot;</td><td>AI học từ dữ liệu con người; dữ liệu thiên kiến tạo ra AI thiên kiến</td></tr><tr><td>&quot;Tốc độ thay đổi công nghệ càng nhanh càng tốt cho xã hội&quot;</td><td>Tốc độ thay đổi quá nhanh có thể để lại những nhóm dân số không thể thích nghi kịp</td></tr><tr><td>&quot;Học online thay thế hoàn toàn học truyền thống&quot;</td><td>Học online bổ sung nhưng không thay thế hoàn toàn; tương tác trực tiếp vẫn có giá trị</td></tr><tr><td>&quot;CNTT giúp tự nhiên giảm bất bình đẳng kinh tế&quot;</td><td>CNTT có thể tăng bất bình đẳng nếu không có chính sách đúng; người giàu tiếp cận công nghệ tốt hơn</td></tr><tr><td>&quot;Big data chỉ được dùng cho mục đích tốt và có lợi&quot;</td><td>Big data bị lạm dụng cho giám sát, phân tích tín dụng thiên vị và can thiệp chính trị</td></tr><tr><td>&quot;Robot sẽ làm mọi công việc tốt hơn con người trong 10 năm&quot;</td><td>AI và robot vẫn kém con người ở sáng tạo, cảm xúc và linh hoạt trong môi trường không cấu trúc</td></tr><tr><td>&quot;Tiền điện tử (crypto) là tiền tệ của tương lai không thể chặn&quot;</td><td>Nhiều quốc gia đã cấm hoặc kiểm soát crypto; rủi ro đầu tư vẫn rất cao</td></tr><tr><td>&quot;Internet of Things làm cuộc sống tiện lợi mà không có rủi ro&quot;</td><td>IoT mở rộng bề mặt tấn công mạng; thiết bị thông minh thường có bảo mật yếu</td></tr><tr><td>&quot;Tin tức online luôn nhanh hơn và chính xác hơn báo truyền thống&quot;</td><td>Tốc độ thường đánh đổi độ chính xác; fake news lan truyền nhanh hơn tin thật</td></tr><tr><td>&quot;Remote work hiệu quả hơn làm văn phòng cho tất cả mọi người&quot;</td><td>Hiệu quả remote work phụ thuộc cá nhân, công việc và điều kiện gia đình</td></tr><tr><td>&quot;Công nghệ nhận dạng khuôn mặt chỉ dùng để bắt tội phạm&quot;</td><td>Nhận dạng khuôn mặt bị dùng để giám sát đại trà, gây lo ngại về quyền tự do</td></tr><tr><td>&quot;Chuyển đổi số tự nhiên giúp chính phủ minh bạch hơn&quot;</td><td>Minh bạch số đòi hỏi chính sách, luật pháp và ý chí chính trị, không tự nhiên có</td></tr><tr><td>&quot;Game nhất định làm trẻ em bạo lực hơn&quot;</td><td>Nghiên cứu không chứng minh được mối liên hệ nhân quả rõ ràng; nhiều yếu tố khác quan trọng hơn</td></tr><tr><td>&quot;Mạng 5G gây hại cho sức khỏe qua bức xạ nguy hiểm&quot;</td><td>5G dùng sóng radio không phải bức xạ ion hóa; các nghiên cứu khoa học không xác nhận tác hại</td></tr><tr><td>&quot;Blockchain đảm bảo mọi giao dịch đều an toàn và hợp pháp&quot;</td><td>Blockchain đảm bảo tính bất biến; vẫn có thể lưu dữ liệu bất hợp pháp và bị tấn công 51%</td></tr><tr><td>&quot;Chuyển đổi số là xu hướng tạm thời, sẽ quay lại cách cũ&quot;</td><td>Chuyển đổi số là quá trình không thể đảo ngược; ngày càng tích hợp sâu vào mọi lĩnh vực</td></tr><tr><td>&quot;Công nghệ giúp người dùng tự kiểm soát thông tin tốt hơn&quot;</td><td>Thuật toán đề xuất thực ra giảm khả năng kiểm soát của người dùng với nội dung họ thấy</td></tr><tr><td>&quot;Làng quê không cần công nghệ vì đã sống tốt không cần internet&quot;</td><td>Tiếp cận internet giúp nông dân cải thiện năng suất, tiếp cận thị trường và dịch vụ y tế</td></tr><tr><td>&quot;Thế hệ Z là bản địa kỹ thuật số nên tự nhiên giỏi công nghệ&quot;</td><td>Quen dùng công nghệ không đồng nghĩa với hiểu biết sâu về kỹ thuật hay bảo mật</td></tr><tr><td>&quot;AI có thể sáng tác nghệ thuật mà không gây tranh cãi bản quyền&quot;</td><td>AI tạo nội dung từ dữ liệu có bản quyền; đang có nhiều vụ kiện về bản quyền AI</td></tr><tr><td>&quot;Xe tự lái sẽ hoàn toàn an toàn và không bao giờ gây tai nạn&quot;</td><td>Xe tự lái vẫn xảy ra tai nạn; còn nhiều thách thức kỹ thuật và pháp lý chưa giải quyết</td></tr><tr><td>&quot;Công nghệ giáo dục (EdTech) tự nhiên cải thiện kết quả học tập&quot;</td><td>Kết quả phụ thuộc vào cách triển khai, chất lượng giáo viên và điều kiện học sinh</td></tr><tr><td>&quot;Phát triển CNTT tốt là điều kiện đủ để nước phát triển giàu mạnh&quot;</td><td>CNTT là điều kiện cần; vẫn cần giáo dục, thể chế, hạ tầng và chính sách phù hợp</td></tr><tr><td>&quot;Công nghệ y tế (HealthTech) sẽ xóa bỏ sự cần thiết của bác sĩ&quot;</td><td>AI hỗ trợ chẩn đoán nhưng không thay thế phán đoán lâm sàng và sự đồng cảm của bác sĩ</td></tr><tr><td>&quot;Mọi dữ liệu trên internet đáng tin cậy vì nhiều người xác nhận&quot;</td><td>Thông tin sai vẫn có thể được nhiều người chia sẻ và xác nhận (hiệu ứng đám đông)</td></tr><tr><td>&quot;App gọi xe, giao đồ ăn chỉ có lợi cho người dùng&quot;</td><td>App giao thức ngữ gây tranh cãi về quyền lợi tài xế và tác động đến giao thông đô thị</td></tr><tr><td>&quot;Thư viện sẽ biến mất vì có Google thay thế&quot;</td><td>Thư viện số và vật lý vẫn đóng vai trò quan trọng trong tiếp cận thông tin có kiểm định</td></tr><tr><td>&quot;CNTT không liên quan đến biến đổi khí hậu&quot;</td><td>Trung tâm dữ liệu tiêu thụ 1-2% điện toàn cầu; khai thác crypto có carbon footprint khổng lồ</td></tr><tr><td>&quot;Người già không thể học và sử dụng công nghệ mới&quot;</td><td>Người cao tuổi có thể học công nghệ với thiết kế phù hợp và hỗ trợ đúng cách</td></tr><tr><td>&quot;Smartphone khiến trẻ em kém thông minh hơn thế hệ trước&quot;</td><td>Tác động phụ thuộc vào nội dung và thời gian sử dụng; công nghệ có thể hỗ trợ học tập nếu dùng đúng</td></tr><tr><td>&quot;Big Data chỉ có ích cho công ty lớn và tập đoàn&quot;</td><td>Các SME và tổ chức phi lợi nhuận cũng hưởng lợi từ phân tích dữ liệu ngày càng dễ tiếp cận</td></tr><tr><td>&quot;Fintech chỉ phục vụ người có điện thoại thông minh cao cấp&quot;</td><td>Nhiều fintech phục vụ tài chính toàn diện (financial inclusion) cho người có điện thoại phổ thông</td></tr><tr><td>&quot;Tự động hóa chỉ xảy ra ở các nước phát triển&quot;</td><td>Việt Nam cũng đang áp dụng tự động hóa trong sản xuất, ngân hàng và dịch vụ</td></tr><tr><td>&quot;Nền kinh tế gig (gig economy) chỉ tốt cho người lao động trẻ&quot;</td><td>Gig economy có thể bóc lột lao động, thiếu phúc lợi xã hội cho mọi độ tuổi</td></tr><tr><td>&quot;AI viết báo là giải pháp cho tin tức chính xác hơn&quot;</td><td>AI có thể tạo tin tức giả rất thuyết phục; cần báo chí con người để kiểm tra và điều tra</td></tr><tr><td>&quot;Công nghệ sinh trắc học (biometrics) không thể bị giả mạo&quot;</td><td>Vân tay, khuôn mặt đều đã bị giả mạo thành công; không có hệ thống bảo mật nào tuyệt đối</td></tr><tr><td>&quot;Chuyển đổi số trong giáo dục nghĩa là thay sách giấy bằng tablet&quot;</td><td>Chuyển đổi số giáo dục bao gồm thay đổi phương pháp dạy học, đánh giá và tương tác</td></tr><tr><td>&quot;Nông nghiệp công nghệ cao chỉ phù hợp với nước giàu&quot;</td><td>Việt Nam và nhiều nước đang phát triển áp dụng thành công nông nghiệp thông minh (smart farming)</td></tr><tr><td>&quot;Thông tin trên Wikipedia không đáng tin cậy vì ai cũng sửa được&quot;</td><td>Wikipedia có hàng triệu người kiểm tra; nghiên cứu cho thấy độ chính xác tương đương nhiều bách khoa toàn thư</td></tr><tr><td>&quot;CNTT phát triển sẽ khiến con người lười biếng và kém năng lực hơn&quot;</td><td>CNTT giải phóng con người khỏi công việc lặp lại; tạo thời gian cho sáng tạo và phát triển cao hơn</td></tr><tr><td>&quot;Mọi startup công nghệ đều thành công vì thị trường số đang bùng nổ&quot;</td><td>90% startup thất bại; thị trường bùng nổ không đảm bảo thành công mà còn tăng cạnh tranh</td></tr><tr><td>&quot;Người dùng có quyền kiểm soát hoàn toàn dữ liệu của mình trên mạng&quot;</td><td>Quyền kiểm soát dữ liệu còn hạn chế; nhiều dữ liệu được thu thập mà người dùng không biết</td></tr><tr><td>&quot;Các công ty công nghệ lớn không có ảnh hưởng đến dân chủ&quot;</td><td>Big Tech có ảnh hưởng lớn đến truyền thông, bầu cử và không gian công cộng số</td></tr><tr><td>&quot;Tương lai của CNTT đã được định trước và không thay đổi được&quot;</td><td>Hướng phát triển công nghệ phụ thuộc vào lựa chọn xã hội, chính sách và giá trị của con người</td></tr><tr><td>&quot;Metaverse sẽ hoàn toàn thay thế thực tế trong vài năm tới&quot;</td><td>Metaverse vẫn đang trong giai đoạn phát triển sơ khai; nhiều dự đoán lạc quan đã không thành hiện thực</td></tr><tr><td>&quot;Công nghệ tự nhiên mang lại công bằng xã hội&quot;</td><td>Công bằng số đòi hỏi thiết kế có chủ đích, chính sách hỗ trợ và xóa khoảng cách tiếp cận</td></tr></tbody></table>`,105)])])}const p=t(c,[["render",o]]);export{e as __pageData,p as default};
